# codec plugin

/*
Codec Plugin 可以支持在 Codec 中自定义编码解码，自定义 Bypass 与字符串处理函数

函数定义非常简单

func(i: string) string
*/

handle = func(origin) {
    domains = str.ParseStringToLines(origin)
    domain = make([]string)
    for index, element = range domains {
        if str.IsHttpURL(element){
            element = str.ReplaceAll(element, "http://", "")
            element = str.ReplaceAll(element, "https://", "")
        }
        if str.Contains(element, "/"){
            element = str.Split(element, "/")[0]
        }
        domain = append(domain, element)
    }
    domain = str.RemoveRepeat(domain)
    return str.Join(domain, "\n")
}
